package com.rita.ecommerceplatform.model

import java.math.BigDecimal
import java.time.LocalDateTime

/**
 * One row of public.ec_product, plus its category name joined from ec_category.
 * Brand, keywords and the rating/sold summary columns are not used yet (D1), so they are left out.
 */
data class Product(
    val productId: Long,
    val categoryId: Int,
    val categoryName: String,
    val name: String,
    val description: String?,
    val sku: String,
    val price: BigDecimal,
    val discountPrice: BigDecimal?,
    // Generated by the database: discountPrice when set, otherwise price.
    val sellingPrice: BigDecimal,
    val stockQuantity: Int,
    val lowStockThreshold: Int?,
    val createdByAdminId: Int,
    val status: ProductStatus,
    val createdAt: LocalDateTime,
    val updatedAt: LocalDateTime,
)

/** Allowed values of ec_product.productstatus (ck__ec_product__status). DELETED is a soft delete. */
enum class ProductStatus { ACTIVE, INACTIVE, DELETED }
